                    className={`w-full rounded-xl p-5 text-left shadow-sm ring-2 transition-all ${active ? "bg-white ring-primary/10" : "bg-surface-container-low opacity-90 ring-transparent hover:opacity-100"} ${done ? "opacity-80" : ""}`}
