import i18n from "i18next";
import { initReactI18next } from "react-i18next";
import LanguageDetector from "i18next-browser-languagedetector";
import en from "./locales/en.json";
import am from "./locales/am.json";

function applyLangToDocument(lng: string) {
  const isAmharic = lng.startsWith("am");
  document.documentElement.lang = isAmharic ? "am" : "en";
  if (isAmharic) {
    document.documentElement.classList.add("lang-am");
  } else {
    document.documentElement.classList.remove("lang-am");
  }
}

i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    resources: {
      en: { translation: en },
      am: { translation: am },
    },
    fallbackLng: "en",
    interpolation: {
      escapeValue: false,
    },
    detection: {
      order: ["localStorage", "navigator"],
      caches: ["localStorage"],
    },
  });

i18n.on("languageChanged", (lng) => {
  applyLangToDocument(lng);
});

applyLangToDocument(i18n.language ?? "en");

export default i18n;

import { useTranslation } from "react-i18next";

export function LanguageToggle({ className = "" }: { className?: string }) {
  const { i18n, t } = useTranslation();
  const current = i18n.language.startsWith("am") ? "am" : "en";

  const switchLang = () => {
    const next = current === "en" ? "am" : "en";
    void i18n.changeLanguage(next);
  };

  return (
    <button
      onClick={switchLang}
      className={`inline-flex items-center gap-1.5 rounded-lg border border-outline-variant/40 bg-surface-container-lowest px-3 py-1.5 text-xs font-bold text-on-surface-variant hover:bg-surface-container transition-all ${className}`}
      title={t("language")}
      aria-label={t("language")}
    >
      <span className="material-symbols-outlined text-sm">translate</span>
      <span className="font-mono tracking-wider">{current === "en" ? "EN" : "አማ"}</span>
      <span className="hidden text-[10px] text-outline sm:inline">
        {current === "en" ? t("english") : t("amharic")}
      </span>
    </button>
  );
}

